`,"content-main.js":`(function () {
  function best(arr) {
    if (!arr || !arr.length) return null;
    var b = null, bs = -1;
    for (var i = 0; i < arr.length; i++) {
      var n = parseInt((arr[i].sizes || "0"), 10) || 0;
      if (n >= bs) { bs = n; b = arr[i]; }
    }
    return b && b.src || (arr[0] && arr[0].src) || null;
  }
  function read() {
    try {
      var ms = navigator.mediaSession;
      if (!ms || !ms.metadata || !ms.metadata.title) return null;
      var md = ms.metadata;
      var a = document.querySelector("audio");
      var pos = a && isFinite(a.currentTime) ? Math.round(a.currentTime * 1000) : 0;
      var dur = a && isFinite(a.duration) ? Math.round(a.duration * 1000) : 0;
      return {
        title: String(md.title || ""),
        artist: String(md.artist || ""),
        album: String(md.album || ""),
        cover: best(md.artwork),
        status: ms.playbackState === "paused" ? "Paused" : "Playing",
        position: pos,
        duration: dur
      };
    } catch (e) { return null; }
  }
  setInterval(function () {
    var d = read();
    if (d) window.postMessage({ __wmrpc: true, data: d }, "*");
  }, 2000);
})();
